<?php
namespace Modules\Pendaftaran\Http\Controllers;
use App\Http\Controllers\Controller;use Illuminate\Http\JsonResponse;use Illuminate\Support\Facades\Storage;use Modules\Pendaftaran\Http\Requests\DaftarRequest;use Modules\Pendaftaran\Models\Daftar;
class PendaftaranController extends Controller{public function index(){return view('pendaftaran::index');}public function getData():JsonResponse{return response()->json(Daftar::latest()->get());}public function store(DaftarRequest $r):JsonResponse{$data=$r->safe()->except('berkas');$f=$r->file('berkas');$data['berkas']=$f->store('berkas_pendaftaran','public');$data['nama_berkas']=$f->getClientOriginalName();Daftar::create($data);return response()->json(['success'=>'Data berhasil disimpan.']);}public function edit(Daftar $daftar):JsonResponse{return response()->json($daftar);}public function update(DaftarRequest $r,Daftar $daftar):JsonResponse{$data=$r->safe()->except('berkas');if($r->hasFile('berkas')){if($daftar->berkas)Storage::disk('public')->delete($daftar->berkas);$f=$r->file('berkas');$data['berkas']=$f->store('berkas_pendaftaran','public');$data['nama_berkas']=$f->getClientOriginalName();}$daftar->update($data);return response()->json(['success'=>'Data berhasil diperbarui.']);}public function destroy(Daftar $daftar):JsonResponse{if($daftar->berkas)Storage::disk('public')->delete($daftar->berkas);$daftar->delete();return response()->json(['success'=>'Data berhasil dihapus.']);}}
